#!/bin/bash
S="$1"; SER=$(/opt/homebrew/bin/adb devices | awk '$2=="device"{print $1}' | head -1); a(){ /opt/homebrew/bin/adb -s "$SER" "$@"; }; slp(){ python3 -I -c "import time,sys;time.sleep(float(sys.argv[1]))" "$1"; }; P=org.opemamalur.scene
grab(){ a exec-out screencap -p > "$S/ui/t/$1.png"; W=$(sips -g pixelWidth "$S/ui/t/$1.png" | tail -1 | awk '{print $2}'); if [ "$W" = 1680 ]; then python3 -I "$S/scripts/pngcrop.py" "$S/ui/t/$1.png" "$S/ui/t/$1-s.png" 1680 1120 840; else sips -Z 840 "$S/ui/t/$1.png" --out "$S/ui/t/$1-s.png" >/dev/null 2>&1; fi; }
start(){ a shell input keyevent KEYCODE_WAKEUP; a shell wm dismiss-keyguard; a shell setprop debug.opem.world town; a shell setprop debug.opem.profile $1; a shell setprop debug.opem.scale $2; a shell setprop debug.opem.crowd 1; a shell setprop debug.opem.shadow $3; a shell setprop debug.opem.walk $4; a shell setprop debug.opem.tour $5; a logcat -c; a shell am force-stop $P; a shell monkey -p $P -c android.intent.category.LAUNCHER 1 >/dev/null 2>&1; }
L(){ a logcat -d -s OpemAmalurScene | grep -E 'PROFILE interval|STREAM cells' | tail -2 | sed -E 's/^.*OpemAmalurScene: //;s/PROFILE //;s/gpu_samples.*//' | cut -c1-125; }
mem(){ a shell dumpsys meminfo $P 2>/dev/null | grep -E 'TOTAL PSS' | tr -s ' ' | cut -c1-24; }
for v in "pack 0" "pack 60" "pack 120" "pack-g2 0" "pack-g8 0" "pack-g8 60"; do set -- $v; a install -r "$S/install/apk-$1.apk" | tail -1 >/dev/null; echo "== $1 shadow=$2m uncapped full res"; start 2 150 $2 0 0; slp 14; L; mem; grab t-$1-$2; a logcat -d -s OpemAmalurScene | grep -E ' E OpemAmalur|FATAL' | grep -v 0x502 | tail -2 | cut -c30-130; done
echo "== g8 + shadow60 sustained at 60 Hz (real play load)"; start 1 150 60 0 0; for q in 1 2 3 4 5 6 7 8; do slp 15; a shell input tap 1200 400; done; L | tail -1; a shell dumpsys battery | grep -m1 temperature | tr -d ' '
a install -r "$S/install/apk-pack.apk" | tail -1 >/dev/null
echo "== walking 90 s, real collision"; start 1 100 0 1 0; for q in 1 2 3 4 5 6 7 8 9; do slp 10; a shell input tap 1200 400; done; L; mem; grab t-walk; a logcat -d -s OpemAmalurScene | grep -cE 'step stopped'; a logcat -d -s OpemAmalurScene | grep -E 'step stopped|recovery failed' | tail -4 | sed -E 's/^.*OpemAmalurScene: //' | cut -c1-120; a logcat -d -s OpemAmalurScene | grep 'PROFILE interval' | sed -E 's/.*worst_ms=([0-9.]+).*/\1/' | tr '\n' ' '; echo
echo "== fast tour 30 m/s, 60 s"; start 1 100 0 0 3000; for q in 1 2 3 4 5 6; do slp 10; a shell input keyevent KEYCODE_WAKEUP; done; L; mem; grab t-tour; a logcat -d -s OpemAmalurScene | grep 'PROFILE interval' | sed -E 's/.*worst_ms=([0-9.]+).*/\1/' | tr '\n' ' '; echo
a shell setprop debug.opem.tour 0; a shell setprop debug.opem.walk 0; a shell setprop debug.opem.shadow 0; a shell setprop debug.opem.profile 0; a shell setprop debug.opem.scale 100; a shell setprop debug.opem.world off; a shell am force-stop $P; echo finished
